 329 m high", "support": ["S2"]}, {"claim": "it is on Bodmin Moor", "support": ["S1"]}, {"claim": "on its south and western slopes are 2 Bronze Age settlements", "support": ["S3"]}, {"claim": "the settlements have associated field enclosures, small cairns, a cist and a propped stone", "support": ["S3"]}], "verdict": "PASS"}, "verify": {"at": "2026-09-30T07:36:57+00:00", "by": "teaser-wb-ws-2026-09-27-06-verify-090", "stage": "verify", "claims": 7, "verdict": "VERIFIED", "unproven": 0, "text_sha256": "612c9634618b080f321f6816037bb83740ceafd504f42c16f569b11455b69a6a"}, "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "web_facts": [], "desc_sha256": "f6121b3f1cac468b18e2e44ed6a29fa3f05d6b827f993f34e5f6e52755f39149", "text_sha256": "612c9634618b080f321f6816037bb83740ceafd504f42c16f569b11455b69a6a"}, "description_citations": [{"n": 1, "url": "https://en.wikipedia.org/w/index.php?title=Leskernick_Hill&oldid=1309316546", "title": "Wikipedia: Leskernick Hill", "domain": "en.wikipedia.org", "license": "CC BY-SA 4.0"}], "_description_provenance": {"v": 1, "ai": "selected", "run": "v3-2026-09-26", "card": null, "lane": "W", "licence": "CC BY-SA 4.0", "sources": [{"id": "W", "url": "https://en.wikipedia.org/w/index.php?title=Leskernick_Hill&oldid=1309316546", "revid": 1309316546, "licence": "CC BY-SA 4.0", "text_sha256": "59f8bf48f0bf56fd23c11a1ae7ddce895752aecbb223c7163c1283d9a482281d", "rev_timestamp": "2025-09-03T10:26:44Z"}], "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "sentences": [{"n": 1, "end": 50, "src": "W", "drop": [[45, 49]], "start": 0}, {"n": 1, "end": 100, "src": "W", "drop": [], "start": 52}, {"n": 1, "end": 678, "src": "W", "drop": [[581, 677]], "start": 426}, {"n": 1, "end": 3577, "src": "W", "drop": [], "start": 3297}], "attribution": {"url": "https://en.wikipedia.org/w/index.php?title=Leskernick_Hill&oldid=1309316546", "title": "Leskernick Hill", "changes": "sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "f6121b3f1cac468b18e2e44ed6a29fa3f05d6b827f993f34e5f6e52755f39149"}}'' restored on Leskernick Hill', 'f6121b3f1cac468b18e2e44ed6a29fa3f05d6b827f993f34e5f6e52755f39149', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A propped stone, small cairns and a stone box grave lie on this hill. Two Bronze Age settlements and their field enclosures lie on the south and western slopes of the hill."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-010 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a hill [S1, S2]; a propped stone lies on the hill [S3]; small cairns lie on the hill [S3]; a stone box grave (a cist) lies on the hill [S3]; there are two settlements [S3]; the settlements are Bronze Age [S3]; the settlements have field enclosures [S3]; the settlements and enclosures lie on the south and western slopes [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-011 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Two settlements lie on this hill [SUPPORTED: https://intarch.ac.uk/journal/issue44/3/4-1.html]; The two settlements are Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Cornish_Bronze_Age]; The two settlements lie on the south and western slopes of the hill [SUPPORTED: https://www.cornish-times.co.uk/news/remote-stone-circle-added-to-at-risk-list-134625]; The settlements have field enclosures of their own [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=46737]; The field enclosures lie on the south and western slopes of the hill [SUPPORTED: https://www.cornish-times.co.uk/news/remote-stone-circle-added-to-at-risk-list-134625]; A propped stone lies on this hill [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=46474]; Small cairns lie on this hill [SUPPORTED: https://www.cornish-times.co.uk/news/remote-stone-circle-added-to-at-risk-list-134625]; A stone box grave lies on this hill [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=46737]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 38;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_prov_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_prov_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_prov_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/card-provenance', 'wb-teaser-prov-s048-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card provenance: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-prov-s048-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-prov-s048-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: this run stamp journalled % row(s) outside unified_sites.(raw_data)', bad;
    END IF;

    RAISE NOTICE 'teaser card provenance: % of % planned cell(s) changed and journalled over 38 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-prov-s048-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/card-provenance'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-prov-s048-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('raw_data')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'raw_data' THEN u.raw_data IS NOT DISTINCT FROM l.new_value::jsonb
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
